function fusionTriee(a, b) {
  if (a.length !== b.length) {
    return "Les tableaux doivent avoir la même longueur.";
  }

  const mergedArray = [];
  let i = 0;
  let j = 0;

  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      mergedArray.push(a[i]);
      i++;
      j++;
    } else {
      mergedArray.push(a[i]);
      i++;
    }
  }

  while (i < a.length) {
    mergedArray.push(a[i]);
    i++;
  }

  while (j < b.length) {
    mergedArray.push(b[j]);
    j++;
  }

  return mergedArray;
}
