    return medianDeuxTries(sorted[mid], sorted.slice(0, mid).concat(sorted[mid+1])).toString();
  } else {
    return medianDeuxTries(sorted[mid + 1], a).toString();
  }
}

function plusLongueSousSuiteCroissante(tab) {
  if (!tab || tab.length === 0) return [];
  let longestSubsequence = "";
  for (let i = 0; i < tab[0].length; i++) {
    for (let j = i + 1; j < tab.length; j++) {
      let subsequence = tab[j].slice(i, j + 1).join("");
      if (subsequence.length > longestSubsequence.length) {
        longestSubsequence = subsequence;
      }
    }
  }

  return longestSubsequence;
}
